#include <stdlib.h>
#include <string.h>
#include <omp.h>

#ifdef __AVX512F__
typedef float vf __attribute__((vector_size(64)));
#define VW 16
#define MR 12
#define MC 96
#define NCG 128
#define ROWS(X) X(0) X(1) X(2) X(3) X(4) X(5) X(6) X(7) X(8) X(9) X(10) X(11)
#else
typedef float vf __attribute__((vector_size(32)));
#define VW 8
#define MR 6
#define MC 72
#define NCG 128
#define ROWS(X) X(0) X(1) X(2) X(3) X(4) X(5)
#endif

#define NR (2 * VW)
#define KC 384

static inline vf ldu(const float *p) { vf v; memcpy(&v, p, sizeof(v)); return v; }
static inline void stu(float *p, vf v) { memcpy(p, &v, sizeof(v)); }

#define DECL(i) vf c##i##_0 = {0}, c##i##_1 = {0};
#define STEP(i) { float a_ = ap[i]; c##i##_0 += a_ * b0; c##i##_1 += a_ * b1; }
#define PFC(i) __builtin_prefetch(c + (size_t)(i) * ldc, 1, 3); \
               __builtin_prefetch(c + (size_t)(i) * ldc + NR - 1, 1, 3);
#define STFULL(i) { float *cp = c + (size_t)(i) * ldc; \
    if (accum) { stu(cp, ldu(cp) + c##i##_0); stu(cp + VW, ldu(cp + VW) + c##i##_1); } \
    else { stu(cp, c##i##_0); stu(cp + VW, c##i##_1); } }
#define STTMP(i) stu(&tmp[i][0], c##i##_0); stu(&tmp[i][VW], c##i##_1);

static inline void kernel(int kc, const float *restrict a, const float *restrict b,
                          float *restrict c, int ldc, int mr, int nr, int accum)
{
    ROWS(DECL)
    if (mr == MR) { ROWS(PFC) }

    #pragma GCC unroll 4
    for (int k = 0; k < kc; k++) {
        vf b0 = *(const vf *)(b + NR * k);
        vf b1 = *(const vf *)(b + NR * k + VW);
        const float *ap = a + MR * k;
        ROWS(STEP)
    }

    if (mr == MR && nr == NR) {
        ROWS(STFULL)
    } else {
        float tmp[MR][NR] __attribute__((aligned(64)));
        ROWS(STTMP)
        for (int i = 0; i < mr; i++) {
            float *cp = c + (size_t)i * ldc;
            if (accum)
                for (int j = 0; j < nr; j++) cp[j] += tmp[i][j];
            else
                for (int j = 0; j < nr; j++) cp[j] = tmp[i][j];
        }
    }
}

static void *alloc64(size_t bytes)
{
    bytes = (bytes + 63) & ~(size_t)63;
    if (bytes == 0) bytes = 64;
    return aligned_alloc(64, bytes);
}

void matmul(const float *A, const float *B, float *C, int n)
{
    if (n <= 0) return;

    int npB = (n + NR - 1) / NR;
    int npA = (n + MR - 1) / MR;
    size_t szB = (size_t)npB * NR * KC;
    size_t szA = (size_t)npA * MR * KC;
    float *Bbuf = (float *)alloc64(2 * szB * sizeof(float));
    float *Abuf = (float *)alloc64(2 * szA * sizeof(float));

    int nib = (n + MC - 1) / MC;
    int njb = (n + NCG - 1) / NCG;
    int nitems = nib * njb;

    #pragma omp parallel
    {
        int parity = 0;
        for (int pc = 0; pc < n; pc += KC, parity ^= 1) {
            int kc = n - pc < KC ? n - pc : KC;
            int accum = pc > 0;
            float *Bp = Bbuf + parity * szB;
            float *Ap = Abuf + parity * szA;

            /* pack A[:, pc:pc+kc] into MR-row panels */
            #pragma omp for schedule(static) nowait
            for (int ip = 0; ip < npA; ip++) {
                float *dst = Ap + (size_t)ip * kc * MR;
                int i0 = ip * MR;
                int mr = n - i0 < MR ? n - i0 : MR;
                for (int ii = 0; ii < MR; ii++) {
                    if (ii < mr) {
                        const float *src = A + (size_t)(i0 + ii) * n + pc;
                        for (int k = 0; k < kc; k++) dst[k * MR + ii] = src[k];
                    } else {
                        for (int k = 0; k < kc; k++) dst[k * MR + ii] = 0.0f;
                    }
                }
            }

            /* pack B[pc:pc+kc, :] into NR-wide panels */
            #pragma omp for schedule(static)
            for (int jp = 0; jp < npB; jp++) {
                float *dst = Bp + (size_t)jp * kc * NR;
                int j0 = jp * NR;
                int nr = n - j0 < NR ? n - j0 : NR;
                if (nr == NR) {
                    for (int k = 0; k < kc; k++)
                        memcpy(dst + k * NR, B + (size_t)(pc + k) * n + j0, NR * sizeof(float));
                } else {
                    for (int k = 0; k < kc; k++) {
                        const float *src = B + (size_t)(pc + k) * n + j0;
                        float *d = dst + k * NR;
                        int j = 0;
                        for (; j < nr; j++) d[j] = src[j];
                        for (; j < NR; j++) d[j] = 0.0f;
                    }
                }
            }

            /* compute; static schedule keeps tile ownership fixed across pc,
               double-buffered packs make the trailing barrier unnecessary */
            #pragma omp for schedule(static) nowait
            for (int it = 0; it < nitems; it++) {
                int jb = it / nib, ib = it % nib;
                int ic = ib * MC;
                int mc = n - ic < MC ? n - ic : MC;
                int jc = jb * NCG;
                int nc = n - jc < NCG ? n - jc : NCG;

                for (int jr = 0; jr < nc; jr += NR) {
                    int j = jc + jr;
                    int nr = n - j < NR ? n - j : NR;
                    const float *bp = Bp + (size_t)(j / NR) * kc * NR;
                    for (int ir = 0; ir < mc; ir += MR) {
                        int i = ic + ir;
                        int mr = n - i < MR ? n - i : MR;
                        kernel(kc, Ap + (size_t)(i / MR) * kc * MR, bp,
                               C + (size_t)i * n + j, n, mr, nr, accum);
                    }
                }
            }
        }
    }
    free(Abuf);
    free(Bbuf);
}
